insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('HEXA','IPV-DTP-HB-Hib','วัคซีนโปลิโอ คอตีบไอกรน บาดทะยัก ฮิป ตับอักเสบบี','2M','REQUIRED',1900,'ACTIVE','DTP_POLIO_COMBO',1,'เข็มที่ 1','วัคซีนรวมป้องกันโปลิโอ คอตีบ ไอกรน บาดทะยัก ฮิบ และ/หรือตับอักเสบบี รับตามช่วงอายุที่กำหนด','หากรับล่าช้า ควรให้แพทย์ตรวจสมุดวัคซีนและจัดตารางต่อเนื่องตามจำนวนเข็มที่ควรได้รับ','แนะนำรับให้ครบตามกำหนด เพื่อสร้างภูมิคุ้มกันต่อโรคร้ายแรงในวัยเด็ก','หากเริ่มรับล่าช้า ควรให้แพทย์ตรวจสมุดวัคซีนก่อนจัดตารางใหม่','Routine',NULL) on conflict (vaccine_id) do nothing;
insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('ROTARIX','Rotarix','วัคซีนโรต้า 1 สายพันธุ์','2M','CHOICE_ROTAVIRUS',1200,'ACTIVE','ROTAVIRUS',2,'เข็มที่ 1','วัคซีนชนิดหยอด ป้องกันโรคอุจจาระร่วงจากไวรัสโรต้า ต้องเริ่มเข็มแรกไม่เกินอายุ 15 สัปดาห์','ต้องเริ่มก่อนอายุ 15 สัปดาห์ และหยอดครบก่อนอายุ 8 เดือน','ควรเริ่มให้เร็วตามช่วงอายุที่กำหนด','ต้องเริ่มเข็มแรกไม่เกินอายุ 15 สัปดาห์ และต้องรับครบก่อนอายุ 8 เดือน','Routine',NULL) on conflict (vaccine_id) do nothing;
insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('ROTATEQ','Rotateq','วัคซีนโรต้า 5 สายพันธุ์','2M','CHOICE_ROTAVIRUS',900,'ACTIVE','ROTAVIRUS',3,'เข็มที่ 1','วัคซีนชนิดหยอด ป้องกันโรคอุจจาระร่วงจากไวรัสโรต้า ต้องเริ่มเข็มแรกไม่เกินอายุ 15 สัปดาห์','ต้องเริ่มก่อนอายุ 15 สัปดาห์ และหยอดครบก่อนอายุ 8 เดือน','ควรเริ่มให้เร็วตามช่วงอายุที่กำหนด','ต้องเริ่มเข็มแรกไม่เกินอายุ 15 สัปดาห์ และต้องรับครบก่อนอายุ 8 เดือน','Routine',NULL) on conflict (vaccine_id) do nothing;
insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('PCV13','PCV13','วัคซีนปอดบวม 13 สายพันธุ์','2M','CHOICE_PCV',2000,'ACTIVE','PCV',4,'เข็มที่ 1','วัคซีนป้องกันโรคปอดอักเสบ หูชั้นกลางอักเสบ และโรครุนแรงจากเชื้อนิวโมคอคคัส','เริ่มอายุ 2 เดือน รับตามกำหนดอายุ 2,4,6 และกระตุ้นที่ 12–15 เดือน /หลัง 6 เดือน: 3 เข็ม เช่น 7, 9, 12–15 เดือน / เริ่มหลัง 1 ปี: 2 เข็ม เช่น 13, 15 เดือน / เริ่มหลัง 2 ปี: 1 เข็ม','แนะนำรับให้ครบตามช่วงอายุ เพื่อป้องกันโรคติดเชื้อรุนแรงจากเชื้อนิวโมคอคคัส','หากเริ่มช้าหรือเคยรับบางเข็มแล้ว ควรให้แพทย์ตรวจสมุดวัคซีนก่อนจัดตารางต่อ','Routine','PCV13') on conflict (vaccine_id) do nothing;
