insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('RSVE 1','RSV Enflonsia','ภูมิสำเร็จรูปป้องกัน RSV','2M','CHOICE_RSV',13900,'ACTIVE','RSV',7,'เข็มที่ 1','ภูมิคุ้มกันสำเร็จรูป ป้องกัน RSV สำหรับทารกแรกเกิด–8 เดือน รับเพียง 1 ครั้งต่อฤดูกาล','โดยทั่วไปแนะนำตั้งแต่แรกเกิดถึงไม่เกิน 8 เดือน และให้เฉพาะปีแรก ยังไม่มีข้อมูลสำหรับปีที่ 2','แนะนำสำหรับทารกแรกเกิดในฤดูกาล RSV','โดยทั่วไปให้เพียง 1 ครั้งต่อฤดูกาล และใช้ตามข้อบ่งชี้ของแพทย์','Recommended','RSV_ENFLONSIA') on conflict (vaccine_id) do nothing;
insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('RSVE 2','RSV Nirsevimab','ภูมิสำเร็จรูปป้องกัน RSV','2M','CHOICE_RSV',15900,'ACTIVE','RSV',8,'เข็มที่ 1','ภูมิคุ้มกันสำเร็จรูป ป้องกัน RSV สำหรับทารกแรกเกิด–8 เดือน รับเพียง 1 ครั้งต่อฤดูกาล','โดยทั่วไปแนะนำตั้งแต่แรกเกิดถึงไม่เกิน 8 เดือน และอาจพิจารณาในปีที่ 2 เฉพาะกลุ่มเสี่ยง','แนะนำสำหรับทารกแรกเกิดในฤดูกาล RSV','โดยทั่วไปให้เพียง 1 ครั้งต่อฤดูกาล และใช้ตามข้อบ่งชี้ของแพทย์','Recommended','RSV_BEYFORTUS') on conflict (vaccine_id) do nothing;
