insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('FLU im','INFLUENZA im','วัคซีนไข้หวัดใหญ่','6M','CHOICE_FLU',600,'ACTIVE','INFLUENZA',20,'เข็มที่ 1','วัคซีนไข้หวัดใหญ่ แนะนำฉีดทุกปี ปีละครั้ง','เด็กอายุน้อยกว่า 9 ปีที่รับครั้งแรก ควรรับ 2 เข็ม ห่างกันอย่างน้อย 1 เดือน หลังจากนั้นปีละครั้ง หากเคยได้รับวัคซีนไข้หวัดใหญ่มาแล้ว ให้รับปีละครั้ง','แนะนำรับทุกปี ปีละครั้ง','เด็กอายุน้อยกว่า 9 ปีที่รับครั้งแรก ควรรับ 2 เข็ม ห่างกันอย่างน้อย 1 เดือน','Recommended','INFLUENZA_IM') on conflict (vaccine_id) do nothing;
insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('FLU Nasal','INFLUENZA  Nasal','วัคซีนไข้หวัดใหญ่','24M','CHOICE_FLU',1350,'ACTIVE','INFLUENZA',21,'Booster','วัคซีนไข้หวัดใหญ่ แนะนำพ่นทุกปี ปีละครั้ง','เริ่มได้ที่อายุ 2-49 ปี หากเคยได้รับวัคซีนไข้หวัดใหญ่มาแล้ว ให้รับปีละครั้ง','เหมาะสำหรับเด็กที่เข้าเกณฑ์และไม่มีข้อห้าม','ไม่เหมาะในเด็กที่มีข้อห้ามบางประการ เช่น ภูมิคุ้มกันบกพร่องหรือโรคประจำตัวบางชนิด ควรปรึกษาแพทย์','Recommended',NULL) on conflict (vaccine_id) do nothing;
